    def _calculate_new_probability(self):
        prior = self.prior

        for obs in self.current_observations.values():
            if obs is not None:
                prior = update_probability(
                    prior,
                    obs["prob_given_true"],
                    obs.get("prob_given_false", 1 - obs["prob_given_true"]),
                )

        for obs in self.current_negative_observations.values():
            if obs is not None:
                prior = update_probability(
                    prior,
                    (1 - obs["prob_given_true"]),
                    (1- obs.get("prob_given_false", 1 - obs["prob_given_true"])),
                )

